entries[183094] = { ["name"] = "Plans: Shadowsteel Helm", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Shadowsteel Helm.\nRequires Shadowlands Blacksmithing (75)\nRequires The Ascended\n- Honored\nSell Price:\nShadowsteel Helm\nBinds when equipped\nHead Plate\n44 Armor\n+18 [Strength or Intellect]\n+27 Stamina\n+ 18 Random Stat 1\n+ 18 Random Stat 2\nDurability 85 / 85\nSell Price:" }
entries[183095] = { ["name"] = "Plans: Shadowsteel Pauldrons", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Shadowsteel Pauldrons.\nRequires Shadowlands Blacksmithing (95)\nRequires The Undying Army\n- Honored\nSell Price:\nShadowsteel Pauldrons\nBinds when equipped\nShoulder Plate\n40 Armor\n+13 [Strength or Intellect]\n+20 Stamina\n+ 13 Random Stat 1\n+ 13 Random Stat 2\nDurability 85 / 85\nSell Price:" }
entries[183096] = { ["name"] = "Formula: Sacred Shard", ["text"] = "Binds when picked up\nUse: Teaches you how to convert an Eternal Crystal into Sacred Shards.\nShatter a Sacred Shard into 3 Soul Dust.\nRequires Shadowlands Enchanting (70)\nRequires The Wild Hunt\n- Honored\nSell Price:\nSoul Dust\nCrafting Reagent\nRequires Sacred Shard" }
entries[183097] = { ["name"] = "Schematic: PHA7-YNX", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a PHA7-YNX.\nRequires Shadowlands Engineering (100)\nRequires The Ascended\n- Exalted\nSell Price:\nPHA7-YNX\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nRequires Wormfed Gear Assembly (15), Mortal Coiled Spring (20), Handful of Laestrite Bolts (25), Elethium Ore (10), Shaded Stone (10), Luminous Flux (20)" }
entries[183098] = { ["name"] = "Technique: Codex of the Still Mind", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Codex of the Still Mind.\nRequires Shadowlands Inscription (50)\nRequires The Ascended\n- Friendly\nSell Price:\nCodex of the Still Mind\nUse: Set out a codex, allowing nearby players to adjust their talents.\n\"Created by players with the Inscription skill. Can be bought and sold on the auction house.\"\nSell Price:\nRequires Luminous Ink (7), Umbral Ink (7), Tranquil Ink , Dark Parchment (75)" }
entries[183099] = { ["name"] = "Design: Revitalizing Jewel Doublet", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Revitalizing Jewel Doublet.\nRequires Shadowlands Jewelcrafting (15)\nRequires Court of Harvesters\n- Honored\nSell Price:\nRevitalizing Jewel Doublet\nUnique-Equipped\nRestores 133 health every 10 sec for each Shadowlands gem you have socketed.\nSell Price:\nRequires Angerseye (2), Laestrite Setting (2)" }
entries[183100] = { ["name"] = "Pattern: Heavy Desolate Armor Kit", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Heavy Desolate Armor Kit.\nRequires Shadowlands Leatherworking (50)\nRequires The Wild Hunt\n- Honored\nSell Price:\nHeavy Desolate Armor Kit\nUse: Increase the stamina of an item worn on the chest by 88 for 2 hrs. Cannot be applied to items higher than level 320.\nSell Price:\nRequires Heavy Desolate Leather (8), Penumbra Thread (4)" }
