entries[183210] = { ["name"] = "Memory of a Fel Bombardment", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFel Bombardment Runecarving Power\nImmolation Aura damage has a chance to grant you a stack of Fel Bombardment, increasing the damage that your next Throw Glaive deals to your primary target by 50% and launching an additional glaive at a nearby target. This effect stacks up to 5 times.\nRunecarve on: Head, Neck, Shoulder\nSource: Quest: The Great Vault\nRequires: Demon Hunter" }
entries[183211] = { ["name"] = "Memory of the Hour of Darkness", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nDarkest Hour Runecarving Power\nYou automatically trigger Darkness when you fall below 35% health. This effect can only occur once every 2 min.\nRunecarve on: Chest, Legs\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Demon Hunter" }
entries[183212] = { ["name"] = "Memory of a Darkglare Medallion", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDarkglare Boon Runecarving Power\nHavoc\nEye Beam has a 40% chance to not incur its cooldown and refund 30 Fury.\n\nVengeance\nFel Devastation has a 40% chance to not incur its cooldown and refund 50 Fury.\nRunecarve on: Neck, Waist\nSource: Dungeon Drop: Margrave Stradama\nRequires: Demon Hunter" }
entries[183213] = { ["name"] = "Memory of the Anguish of the Collective", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCollective Anguish Runecarving Power\nHavoc\nCasting Eye Beam summons an allied Vengeance Demon Hunter who casts Fel Devastation.\n\nVengeance\nCasting Fel Devastation summons an allied Havoc Demon Hunter who casts Eye Beam.\nRunecarve on: Wrist, Back\nSource: Raid Drop: Stone Legion Generals\nRequires: Demon Hunter" }
entries[183214] = { ["name"] = "Memory of the Chaos Theory", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nChaos Theory Runecarving Power\nBlade Dance has a 30% chance to grant you Chaotic Blades, increasing the damage of Chaos Strike by 50% and its chance to refund Fury by an additional 60% for 8 sec. (500ms cooldown)\nRunecarve on: Waist, Hands\nSource: Raid Drop: Sire Denathrius\nRequires: Demon Hunter (Havoc)" }
entries[183215] = { ["name"] = "Memory of an Erratic Fel Core", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nErratic Fel Core Runecarving Power\nThe cooldown of Fel Rush is reduced by 30%.\nRunecarve on: Feet, Finger\nSource: World Boss Drop: Nurgash Muckformed\nRequires: Demon Hunter (Havoc)" }
entries[183216] = { ["name"] = "Memory of a Burning Wound", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBurning Wound Runecarving Power Melee Range\nDemon's Bite leaves an open wound on your enemy dealing (100% of Attack Power) Chaos damage over 15 sec and increasing damage taken from your Immolation Aura by 65%.\nRunecarve on: Chest, Back\nSource: Dungeon Drop: The Manastorms\nRequires: Demon Hunter (Havoc)" }
entries[183217] = { ["name"] = "Memory of my Darker Nature", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDarker Nature Runecarving Power\nEnemies slain within 4 sec of taking damage from Eye Beam have a 25% chance to convert their Soul Fragment into a Demon Soul Fragment.\nRunecarve on: Shoulder, Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Demon Hunter (Havoc)" }
entries[183218] = { ["name"] = "Memory of a Fortified Fel Flame", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFel Flame Fortification Runecarving Power\nYou take 15% reduced magic damage while Immolation Aura is active.\nRunecarve on: Waist, Finger\nSource: Raid Drop: Lady Inerva Darkvein\nRequires: Demon Hunter (Vengeance)" }
entries[183219] = { ["name"] = "Memory of Soul of Fire", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFiery Soul Runecarving Power\nEach Soul Fragment consumed by Soul Cleave reduces the cooldown of Fiery Brand by 2 sec.\nRunecarve on: Wrist, Hands\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Demon Hunter (Vengeance)" }
entries[183220] = { ["name"] = "Memory of Razelikh's Defilement", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRazelikh's Defilement Runecarving Power\nSoul Cleave reduces the remaining cooldown on a random Sigil by 8 sec . (500ms cooldown)\nRunecarve on: Legs, Wrist\nSource: Dungeon Drop: Xav the Unfallen\nRequires: Demon Hunter (Vengeance)" }
entries[183221] = { ["name"] = "Memory of the Dark Flame Spirit", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSpirit of the Darkness Flame Runecarving Power\nYour Fiery Brand now heals you for 100% of its initial damage done over 8 sec, and each enemy hit by your Sigil of Flame increases the instant damage of your next Fiery Brand by 15%, stacking up to 15 times.\nRunecarve on: Head, Neck\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Demon Hunter (Vengeance)" }
entries[183222] = { ["name"] = "Memory of the Elder Druid", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nOath of the Elder Druid Runecarving Power\nEffects of Thick Hide, Astral Influence, Feline Swiftness, and Ysera's Gift increased by 75%.\n\nWhen you shift into your Affinity's form, you gain Heart of the Wild for 10 sec, once every 1 min.\nRunecarve on: Shoulder, Wrist\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Druid" }
entries[183223] = { ["name"] = "Memory of the Circle of Life and Death", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCircle of Life and Death Runecarving Power\nYour damage over time effects deal their damage in 25% less time, and your healing over time effects in 15% less time.\nRunecarve on: Head, Finger\nSource: Raid Drop: Stone Legion Generals\nRequires: Druid" }
entries[183224] = { ["name"] = "Memory of a Deep Focus Draught", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDraught of Deep Focus Runecarving Power\nWhen Moonfire, Rake, Rip, or Rejuvenation are active on a single target, their effects are increased 40%.\nRunecarve on: Neck, Chest\nSource: Quest: The Great Vault\nRequires: Druid" }
entries[183225] = { ["name"] = "Memory of Lycara", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nLycara's Fleeting Glimpse Runecarving Power\nEvery 45 sec while in combat, cast a spell based on your form:\n\nNo Form: Wild Growth\nCat Form: Primal Wrath\nBear Form: Barkskin\nMoonkin Form: Starfall\nTravel Form: Stampeding Roar\nRunecarve on: Waist, Feet\nSource: Dungeon Drop: Mordretha, the Endless Empress\nRequires: Druid" }
entries[183226] = { ["name"] = "Memory of the Balance of All Things", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBalance of All Things Runecarving Power\nEntering Eclipse increases your critical strike chance with Arcane or Nature spells by 24%, decreasing by 3% every 1 sec.\nRunecarve on: Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Druid (Balance)" }
entries[183227] = { ["name"] = "Memory of Oneth", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nOneth's Clear Vision Runecarving Power\nStarsurge has a 20% chance to make Starfall free. Starfall has a 40% chance to make Starsurge free.\nRunecarve on: Feet, Back\nSource: Raid Drop: Sire Denathrius\nRequires: Druid (Balance)" }
entries[183228] = { ["name"] = "Memory of Arcane Pulsars", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Restore the following memory to the Runecarver:\n\nPrimordial Arcanic Pulsar Runecarving Power\nEvery 300 Astral Power spent grants Celestial Alignment for 12 sec.\nRunecarve on: Shoulder, Hands, Finger\nSource: Drop: The Maw, Wrath of the Jailer\nRequires: Druid (Balance)" }
entries[183229] = { ["name"] = "Memory of a Timeworn Dreambinder", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nTimeworn Dreambinder Runecarving Power\nStarsurge and Starfall reduce the cost of Starsurge and Starfall by 10% and increase their damage by 10% for 5 sec, stacking up to 2 times.\nRunecarve on: Chest, Finger\nSource: Dungeon Drop: Tred'ova\nRequires: Druid (Balance)" }
entries[183230] = { ["name"] = "Memory of the Apex Predator", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nApex Predator's Craving Runecarving Power\nRip damage has a 4% chance to make your next Ferocious Bite free and deal the maximum damage.\nRunecarve on: Shoulder, Waist\nSource: Drop: Torghast, Tower of the Damned. The Upper Reaches, Layer 3+\nRequires: Druid (Feral)" }
entries[183231] = { ["name"] = "Memory of a Cat-Eye Curio", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCat-Eye Curio Runecarving Power\nClearcast abilities generate 30% of their Energy cost, and your maximum energy is increased by 60.\nRunecarve on: Neck, Finger\nSource: Dungeon Drop: Kin-Tara\nRequires: Druid (Feral)" }
entries[183232] = { ["name"] = "Memory of a Symmetrical Eye", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEye of Fearful Symmetry Runecarving Power\nTiger's Fury causes your next 2 finishing moves to restore 2 combo points.\nRunecarve on: Head, Neck, Hands\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Druid (Feral)" }
entries[183233] = { ["name"] = "Memory of the Frenzyband", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFrenzyband Runecarving Power 100 yd range\nCombo point-generating abilities reduce the cooldown of [ Incarnation: Avatar of Ashamane : Incarnation: King of the Jungle by 0.3 / Berserk by 0.3] sec.\n\nDuring [ Incarnation: Avatar of Ashamane : Incarnation: King of the Jungle / Berserk], they cause the target to bleed for an additonal 150% of their damage over 8 sec.\nRunecarve on: Waist, Wrist\nSource: Raid Drop: Sludgefist\nRequires: Druid (Feral)" }
entries[183234] = { ["name"] = "Memory of a Luffa-Infused Embrace", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nLuffa-Infused Embrace Runecarving Power\nThrash has 20% increased damage, 30% increased radius, and can stack 1 additional time.\nRunecarve on: Chest, Back\nSource: Dungeon Drop: Kryxis the Voracious\nRequires: Druid (Guardian)" }
entries[183235] = { ["name"] = "Memory of the Natural Order", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThe Natural Order's Will Runecarving Power\nBarkskin reduces damage by an additional 10%. When it begins or ends in Bear Form, you gain Ironfur and Frenzied Regeneration.\nRunecarve on: Head, Wrist, Hands\nSource: Raid Drop: Huntsman Altimor\nRequires: Druid (Guardian)" }
entries[183236] = { ["name"] = "Memory of Ursoc", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nUrsoc's Fury Remembered Runecarving Power\nIn Bear Form, Thrash has a 15% chance to trigger an additional Thrash.\n\nThrash grants you an absorb shield for 75% of all damage it deals.\nRunecarve on: Legs, Back\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Druid (Guardian)" }
entries[183237] = { ["name"] = "Memory of the Sleeper", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nLegacy of the Sleeper Runecarving Power\n[ Incarnation: Guardian of Ursoc / Berserk in Bear Form] grants 0% increased damage, 25% Leech, and immunity to effects that cause loss of control of your character.\n\nIts cooldown is reduced by 30 sec.\nRunecarve on: Waist, Feet\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Druid (Guardian)" }
entries[183238] = { ["name"] = "Memory of the Verdant Infusion", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nVerdant Infusion Runecarving Power\nSwiftmend no longer consumes a heal over time effect, and extends the duration of your heal over time effects on the target by 10 sec.\nRunecarve on: Shoulder, Hands, Back\nSource: World Boss Drop: Oranomonos the Everbranching\nRequires: Druid (Restoration)" }
entries[183239] = { ["name"] = "Memory of an Unending Growth", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nVision of Unending Growth Runecarving Power\nRejuvenation healing has a 2.5% chance to create a new Rejuvenation on a nearby target. (Proc chance: 3%)\nRunecarve on: Head, Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Druid (Restoration)" }
entries[183240] = { ["name"] = "Memory of the Mother Tree", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMemory of the Mother Tree Runecarving Power\nWild Growth has a 40% chance to cause your next Rejuvenation or Regrowth to apply to 3 additional allies within 20 yards of the target. (Proc chance: 40%)\nRunecarve on: Legs, Wrist\nSource: Raid Drop: Lady Inerva Darkvein\nRequires: Druid (Restoration)" }
entries[183241] = { ["name"] = "Memory of the Dark Titan", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThe Dark Titan's Lesson Runecarving Power\nYou may Lifebloom two targets at once, but Lifebloom's healing is reduced by 10%.\nRunecarve on: Neck, Back\nSource: Dungeon Drop: Lord Chamberlain\nRequires: Druid (Restoration)" }
entries[183242] = { ["name"] = "Memory of Eonar", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nYou must be Revered with The Wild Hunt and have Runecarving unlocked to purchase this memory.\n\nEcho of Eonar Runecarving Power Approximately 1 procs per minute\nYour spells and abilities have a low chance to summon a spiritual familiar to your side, increasing your damage by 10%, healing by 10% or damage reduction by 10% for 10 sec based on your role. This effect is duplicated on up to 3 allies at 50% effectiveness, preferring allies with the same role.\nRunecarve on: Waist, Wrist, Finger\nSource: You must be Revered with The Wild Hunt and have Runecarving unlocked to purchase this memory." }
entries[183243] = { ["name"] = "Memory of the Arbiter's Judgment", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nYou must be Revered with The Ascended and have Runecarving unlocked to purchase this memory.\n\nJudgment of the Arbiter Level 80 Runecarving Power Approximately 6 procs per minute\nDealing damage has a high chance to release a blast of spiritual energy for 2003 Shadow damage. If another ally who bears the Judgment of the Arbiter is within 5-20 yards of you, the blast will also arc to them, dealing 2003 Shadow damage to enemies in the arc.\nRunecarve on: Wrist, Hands, Finger\nSource: You must be Revered with The Ascended and have Runecarving unlocked to purchase this memory." }
entries[183244] = { ["name"] = "Memory of the Rattle of the Maw", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nYou must be Revered with The Undying Army and have Runecarving unlocked to purchase this memory.\n\nMaw Rattle Level 80 Runecarving Power Approximately 6 procs per minute\nKilling an enemy has a high chance to summon an Explosive Mawrat at the corpse's location. After 6 sec the mawrat will explode, dealing 31747 Nature damage to all nearby enemies, poisoning them and decreasing their damage done by 5% for 10 sec.\nRunecarve on: Legs, Feet, Hands\nSource: You must be Revered with The Undying Army and have Runecarving unlocked to purchase this memory." }
entries[183245] = { ["name"] = "Memory of Norgannon", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nYou must be Revered with the Court of Harvesters and have Runecarving unlocked to purchase this memory.\n\nNorgannon's Sagacity Runecarving Power\nCasting a spell grants Sagacity, stacking up to 10 times. When you move, you are able to cast while moving for 0.5 sec for each stack of Sagacity. (100ms cooldown)\nRunecarve on: Legs, Feet, Back\nSource: You must be Revered with the Court of Harvesters and have Runecarving unlocked to purchase this memory." }
entries[183246] = { ["name"] = "Memory of Sephuz", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nSephuz's Proclamation Level 80 Runecarving Power\nReduce the effectiveness of crowd controlling effects by 10%. Successfully applying a loss of control effect to an enemy, interrupting an enemy, or dispelling any target will increase all your secondary stats by 217 for 15 sec. This effect cannot occur more than once every 30 seconds. (30s cooldown)\nRunecarve on: Neck, Shoulder, Chest\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory." }
entries[183247] = { ["name"] = "Memory of a Stable Phantasma Lure", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nStable Phantasma Lure Runecarving Power Approximately 4 procs per minute\nIncreases Phantasma earned by 25%. Looting Phantasma from enemies has a chance to summon a Phantasma Demon which will begin running in a random direction. Killing it increases Phantasma earned for the entire party by an additional 10% for 1 min.\nRunecarve on: Neck, Wrist, Back\nSource: Drop: Torghast, Tower of the Damned. Layer 6+" }
entries[183248] = { ["name"] = "Memory of Jailer's Eye", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nYou must be Ambivalent with Ve'nari and have Runecarving unlocked to purchase this memory.\n\nThird Eye of the Jailer Runecarving Power\nKilling an enemy grants you the Third Eye, increasing your Primary Stat by 1% for 10 sec, stacking up to 7 and increasing the duration by 1 sec for each additional stack. The duration of the Third Eye is increased by 50% while in the Maw.\nRunecarve on: Head, Neck, Shoulder, Waist\nSource: You must be Ambivalent with Ve'nari and have Runecarving unlocked to purchase this memory." }
entries[183249] = { ["name"] = "Memory of a Vital Sacrifice", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nRequires Renown 14\n\nVitality Sacrifice Runecarving Power\nTaking significant damage from a player or Elite enemy increases your damage and healing by 3% of the damage taken, up to a maximum of 9% for 20 sec.\n\nThis effect can only occur every 30 sec. (30s cooldown)\nRunecarve on: Head, Shoulder, Chest, Finger\nSource: Purchased for Anima from the Renown Quartermaster. You must be Renown 14 with your Covenant to purchase this memory." }
entries[183250] = { ["name"] = "Memory of the Wild Call", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCall of the Wild Runecarving Power\nThe cooldown of all of your Aspects [ Marksmanship : and Trueshot / Survival : and Coordinated Assault ] is reduced by 35%.\nRunecarve on: Wrist, Finger\nSource: Raid Drop: Stone Legion Generals\nRequires: Hunter" }
entries[183251] = { ["name"] = "Memory of a Craven Strategem", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCraven Strategem Runecarving Power Instant\nFeign Death cooldown reduced by 15.0 sec, and Feign Death now removes most negative status effects from yourself.\nRunecarve on: Neck, Chest\nSource: Quest: The Great Vault\nRequires: Hunter" }
entries[183252] = { ["name"] = "Memory of a Trapping Apparatus", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nNesingwary's Trapping Apparatus Runecarving Power\nWhenever a trap is triggered, gain 45 Focus and increase all Focus gained by 100% for 5 sec.\nRunecarve on: Neck, Waist, Feet\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Hunter" }
entries[183253] = { ["name"] = "Memory of the Soulforge Embers", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSoulforge Embers Runecarving Power\nLaunching a Flare into your Tar Trap causes up to 5 enemies inside of the Tar Trap to burn for (240% of Attack Power) Fire damage over 12 sec.\nRunecarve on: Head, Shoulder, Finger\nSource: Dungeon Drop: Ingra Maloch\nRequires: Hunter" }
entries[183254] = { ["name"] = "Memory of a Dire Command", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDire Command Runecarving Power\nKill Command has a 30% chance to also summon a Dire Beast to attack your target.\nRunecarve on: Chest, Finger\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Hunter (Beast Mastery)" }
entries[183255] = { ["name"] = "Memory of the Flamewaker", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFlamewaker's Cobra Sting Runecarving Power\nCobra Shot has a 50% chance to make your next Kill Command consume no Focus. (Proc chance: 50%)\nRunecarve on: Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Hunter (Beast Mastery)" }
entries[183256] = { ["name"] = "Memory of the Eredun War Order", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nQa'pla, Eredun War Order Runecarving Power\nBarbed Shot deals 10% increased damage, and applying Barbed Shot now also resets the cooldown of Kill Command.\nRunecarve on: Shoulder, Hands\nSource: Raid Drop: Sire Denathrius\nRequires: Hunter (Beast Mastery)" }
entries[183257] = { ["name"] = "Memory of the Rylakstalker's Fangs", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRylakstalker's Piercing Fangs Runecarving Power\nWhile Bestial Wrath is active, your pet's critical damage dealt is increased by 35%.\nRunecarve on: Legs, Feet, Back\nSource: Dungeon Drop: Devos, Paragon of Doubt\nRequires: Hunter (Beast Mastery)" }
entries[183258] = { ["name"] = "Memory of Eagletalon's True Focus", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEagletalon's True Focus Runecarving Power\nTrueshot lasts an additional 3.0 sec and reduces the Focus cost of all of your abilities by 25%.\nRunecarve on: Head, Waist, Hands\nSource: Raid Drop: Huntsman Altimor\nRequires: Hunter (Marksmanship)" }
entries[183259] = { ["name"] = "Memory of the Unblinking Vigil", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSecrets of the Unblinking Vigil Runecarving Power\nWhen you gain the Trick Shots effect, you have a 50% chance to refund a charge of Aimed Shot, and cause your next Aimed Shot to not consume any Focus.\nRunecarve on: Wrist, Hands\nSource: Drop: Torghast, Tower of the Damned. The Upper Reaches, Layer 3+\nRequires: Hunter (Marksmanship)" }
entries[183260] = { ["name"] = "Memory of the Serpentstalker's Trickery", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSerpentstalker's Trickery Runecarving Power\nAimed Shot also fires a Serpent Sting at the primary target.\nRunecarve on: Shoulder, Finger\nSource: Dungeon Drop: Domina Venomblade\nRequires: Hunter (Marksmanship)" }
entries[183261] = { ["name"] = "Memory of Surging Shots", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSurging Shots Runecarving Power\nRapid Fire deals 35% additional damage, and Aimed Shot has a 15% chance to reset the cooldown of Rapid Fire. (Proc chance: 15%)\nRunecarve on: Neck, Wrist\nSource: World Boss Drop: Oranomonos the Everbranching\nRequires: Hunter (Marksmanship)" }
entries[183262] = { ["name"] = "Memory of the Butcher's Bone Fragments", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nButcher's Bone Fragments Runecarving Power\n[ Mongoose Bite / Raptor Strike] increases the damage of your next [ Butchery / Carve] by 20%, stacking up to 6 times.\nRunecarve on: Chest, Back\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Hunter (Survival)" }
entries[183263] = { ["name"] = "Memory of Poisonous Injectors", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nLatent Poison Injectors Runecarving Power\nSerpent Sting's damage applies Latent Poison to the target, stacking up to 10 times. [ Mongoose Bite / Raptor Strike] consumes all stacks of Latent Poison, dealing (20.7% of Attack Power) Nature damage to the target per stack consumed.\nRunecarve on: Head, Hands\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Hunter (Survival)" }
entries[183264] = { ["name"] = "Memory of the Rylakstalker's Strikes", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRylakstalker's Confounding Strikes Runecarving Power\n[ Mongoose Bite / Raptor Strike] has a 15% chance to reset the cooldown of Wildfire Bomb. (Proc chance: 15%)\nRunecarve on: Legs, Back\nSource: Raid Drop: Sludgefist\nRequires: Hunter (Survival)" }
entries[183265] = { ["name"] = "Memory of a Wildfire Cluster", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nWildfire Cluster Runecarving Power\nWildfire Bomb drops an additional cluster of bombs around the target, each exploding for (33% of Attack Power) Fire damage. Damage is reduced beyond 8 targets.\nRunecarve on: Waist, Legs\nSource: Dungeon Drop: Dealer Xy'exa\nRequires: Hunter (Survival)" }
entries[183266] = { ["name"] = "Memory of the Disciplinary Command", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDisciplinary Command Runecarving Power\nCasting a Frost, Fire and Arcane spell within 10 sec of each other increases your Critical Strike damage of all your spells by 20%. This effect can only occur once every 30 sec.\nRunecarve on: Wrist, Finger\nSource: Dungeon Drop: Mistcaller" }
entries[183267] = { ["name"] = "Memory of an Expanded Potential", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nExpanded Potential Runecarving Power Approximately 2 procs per minute\nYour Fireball, Frostbolt and Arcane Blast have a chance to give you Expanded Potential, which causes your next Hot Streak, Brain Freeze or Clearcasting to not be consumed.\nRunecarve on: Waist, Feet\nSource: Raid Drop: Stone Legion Generals\nRequires: Mage" }
entries[183268] = { ["name"] = "Memory of a Grisly Icicle", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nGrisly Icicle Runecarving Power\nYour spells no longer break Frost Nova, and enemies damaged by Frost Nova take 15% increased damage from your Fire and Arcane spells for 8 sec.\nRunecarve on: Head, Neck, Shoulder\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Mage" }
entries[183269] = { ["name"] = "Memory of the Triune Ward", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nTriune Ward Runecarving Power\nCasting any Barrier spell grants the effects of Blazing Barrier, Ice Barrier, and Prismatic Barrier. Each absorb shield has 65% effectiveness. (750ms cooldown)\nRunecarve on: Neck, Chest\nSource: Quest: The Great Vault\nRequires: Mage" }
entries[183270] = { ["name"] = "Memory of an Arcane Bombardment", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nArcane Bombardment Runecarving Power\nArcane Barrage deals an additional 130% damage against targets below 35% health.\nRunecarve on: Feet, Back\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Mage (Arcane)" }
entries[183271] = { ["name"] = "Memory of the Infinite Arcane", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nArcane Harmony Runecarving Power\nEach time Arcane Missiles hits an enemy, the damage of your next Arcane Barrage is increased by 8%. This effect stacks up to 18 times.\nRunecarve on: Shoulder, Hands\nSource: Dungeon Drop: The Manastorms\nRequires: Mage (Arcane)" }
entries[183272] = { ["name"] = "Memory of a Siphoning Storm", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSiphon Storm Runecarving Power\nEvocation grants 1 Arcane Charge, and while channeling Evocation, your Intellect is increased by 2% every 0.5 sec. Lasts 30 sec.\nRunecarve on: Legs, Feet, Hands\nSource: Raid Drop: Sludgefist\nRequires: Mage (Arcane)" }
entries[183273] = { ["name"] = "Memory of a Temporal Warp", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nTemporal Warp Runecarving Power\nWhile you have Temporal Displacement or other similar effects, you may use Time Warp to grant yourself 30% Haste for 40 sec.\nRunecarve on: Chest, Finger\nSource: Drop: Torghast, Tower of the Damned. The Upper Reaches, Layer 3+" }
entries[183274] = { ["name"] = "Memory of a Fevered Incantation", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFevered Incantation Runecarving Power\nEach consecutive critical strike you deal increases critical strike damage you deal by 3%, up to 15%.\nRunecarve on: Head, Waist, Hands\nSource: World Boss Drop: Oranomonos the Everbranching\nRequires: Mage (Fire)" }
entries[183275] = { ["name"] = "Memory of the Firestorm", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFirestorm Runecarving Power Approximately 1.66 procs per minute\nWhen Hot Streak activates, you have a low chance to cause all Pyroblasts and Flamestrikes to have no cast time and be guaranteed critical strikes for 4 sec.\nRunecarve on: Shoulder, Finger\nSource: Dungeon Drop: Lord Chamberlain\nRequires: Mage (Fire)" }
entries[183276] = { ["name"] = "Memory of the Molten Sky", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMolten Skyfall Runecarving Power\nDamaging an enemy with 18 Fireballs or Pyroblasts causes your next Fireball to call down a Meteor on your target. Hitting an enemy player counts as double.\nRunecarve on: Neck, Wrist\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Mage (Fire)" }
entries[183277] = { ["name"] = "Memory of the Sun King", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSun King's Blessing Runecarving Power\nAfter consuming 8 Hot Streaks, your next non-instant Pyroblast cast within 15 sec grants you Combustion for 6 sec.\nRunecarve on: Wrist, Hands\nSource: Raid Drop: Sun King's Salvation\nRequires: Mage (Fire)" }
entries[183278] = { ["name"] = "Memory of the Cold Front", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCold Front Runecarving Power\nCasting 30 Frostbolts or Flurries calls down a Frozen Orb toward your target. Hitting an enemy player counts as double.\nRunecarve on: Chest, Back\nSource: Dungeon Drop: Nalthor the Rimebinder\nRequires: Mage (Frost)" }
entries[183279] = { ["name"] = "Memory of the Freezing Winds", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFreezing Winds Runecarving Power\nWhile Frozen Orb is active, you gain Fingers of Frost every 2 sec.\nRunecarve on: Head, Hands\nSource: Raid Drop: Sire Denathrius\nRequires: Mage (Frost)" }
entries[183280] = { ["name"] = "Memory of Fragments of Ice", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nGlacial Fragments Runecarving Power\nIce Lance has a 20% chance to explode into shards of ice when it hits a target, dealing (40% of Spell Power) Frost damage to all enemies near your target. Deals reduced damage beyond 5 targets. This chance is increased to 100% if your target is standing in a Blizzard.\nRunecarve on: Legs, Back\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Mage (Frost)" }
entries[183281] = { ["name"] = "Memory of Slick Ice", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSlick Ice Runecarving Power\nWhile Icy Veins is active, each Frostbolt you cast reduces the cast time of Frostbolt by 2% and increases its damage by 2%, stacking up to 10 times.\nRunecarve on: Waist, Legs\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Mage (Frost)" }
entries[183282] = { ["name"] = "Memory of the Fatal Touch", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFatal Touch Runecarving Power Instant\nTouch of Death cooldown reduced by 120 sec.\nRunecarve on: Wrist, Finger\nSource: Dungeon Drop: Mueh'zala\nRequires: Monk" }
entries[183283] = { ["name"] = "Memory of the Invoker", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nInvoker's Delight Runecarving Power\nYou gain 33% haste for 20 sec after summoning your Celestial.\nRunecarve on: Head, Shoulder, Back\nSource: Raid Drop: Stone Legion Generals\nRequires: Monk" }
entries[183284] = { ["name"] = "Memory of Escaping from Reality", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEscape from Reality Runecarving Power\nAfter you use Transcendence: Transfer, you can use Transcendence: Transfer again within 10 sec, ignoring its cooldown.\n\nDuring this time, if you cast Vivify on yourself, its healing is increased by 70% and 50% of its cost is refunded.\nRunecarve on: Neck, Chest\nSource: Quest: The Great Vault\nRequires: Monk" }
entries[183285] = { ["name"] = "Memory of the Swiftsure Wraps", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nRoll Out Runecarving Power Instant\nDuring [ Chi Torpedo / Roll], you are immune to roots and snares.\nRunecarve on: Waist, Feet\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Monk" }
entries[183286] = { ["name"] = "Memory of Shaohao", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nShaohao's Might Runecarving Power\nTiger Palm has a 40% chance to deal 300% of normal damage and reduce the remaining cooldown of your Brews by 2 additional sec.\nRunecarve on: Chest, Finger\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Monk (Brewmaster)" }
entries[183287] = { ["name"] = "Memory of Charred Passions", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCharred Passions Runecarving Power\nYour Breath of Fire ignites your right leg in flame for 8 sec, causing your Blackout Kick and Spinning Crane Kick to deal 100% additional damage as Fire damage and refresh the duration of your Breath of Fire on the target.\nRunecarve on: Feet, Back\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Monk (Brewmaster)" }
entries[183288] = { ["name"] = "Memory of a Celestial Infusion", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMighty Pour Runecarving Power\nPurifying Brew has a 35% chance to not consume a charge and Celestial Brew increases your Armor by 50% for 8 sec.\nRunecarve on: Legs, Feet\nSource: Raid Drop: Sire Denathrius\nRequires: Monk (Brewmaster)" }
entries[183289] = { ["name"] = "Memory of Stormstout", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nStormstout's Last Keg Runecarving Power\nKeg Smash deals 30% additional damage, and has 1 additional [charge][charges].\nRunecarve on: Shoulder, Waist, Hands\nSource: Dungeon Drop: General Kaal\nRequires: Monk (Brewmaster)" }
entries[183290] = { ["name"] = "Memory of Ancient Teachings", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nAncient Teachings of the Monastery Runecarving Power\nAfter casting Essence Font, your Tiger Palm, Blackout Kick, and Rising Sun Kick heal an injured ally within 20 yards for 250% of the damage done. Lasts 15 sec.\nRunecarve on: Wrist, Hands\nSource: Dungeon Drop: Devos, Paragon of Doubt\nRequires: Monk (Mistweaver)" }
entries[183291] = { ["name"] = "Memory of Yu'lon", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nYu'lon's Whisper Runecarving Power 100 yd range\nActivating Thunder Focus Tea causes you to exhale the breath of Yu'lon, healing up to 6 allies within 15 yards for [(60% of Spell Power) * (3)] over 2 sec.\nRunecarve on: Shoulder, Finger\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Monk (Mistweaver)" }
entries[183292] = { ["name"] = "Memory of Clouded Focus", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nClouded Focus Runecarving Power\nHealing with Enveloping Mists or Vivify while channeling Soothing Mists increases their healing done by 20% and reduces their mana cost by 20%. Stacks up to 3 times.\n\nWhen your Soothing Mists channel ends, this effect is cancelled.\nRunecarve on: Neck, Wrist\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Monk (Mistweaver)" }
entries[183293] = { ["name"] = "Memory of the Morning's Tear", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nTear of Morning Runecarving Power\nCasting Vivify or Enveloping Mist on a target with Renewing Mist has a 10% chance to spread the Renewing Mist to another target.\n\nYour Vivify healing through Renewing Mist is increased by 20% and your Enveloping Mist also heals allies with Renewing Mist for 20% of its healing.\nRunecarve on: Head, Waist\nSource: Raid Drop: Sludgefist\nRequires: Monk (Mistweaver)" }
entries[183294] = { ["name"] = "Memory of the Jade Ignition", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nJade Ignition Runecarving Power\nWhenever you deal damage to a target with Fists of Fury, you gain a stack of Chi Energy up to a maximum of 30 stacks.\n\nUsing Spinning Crane Kick will cause the energy to detonate in a Chi Explosion, dealing (65% of Attack Power) damage to all enemies within 8 yards. The damage is increased by 5% for each stack of Chi Energy.\nRunecarve on: Legs, Back\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Monk (Windwalker)" }
entries[183295] = { ["name"] = "Memory of Keefer", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nKeefer's Skyreach Runecarving Power\nTiger Palm now has a 10 yard range and dashes you to the target when used.\n\nTiger Palm also applies an effect which increases your critical strike chance by 50% for 6 sec on the target. This effect cannot be applied more than once every 1 min per target.\nRunecarve on: Head, Neck, Hands\nSource: World Boss Drop: Mortanis\nRequires: Monk (Windwalker)" }
entries[183296] = { ["name"] = "Memory of the Last Emperor", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nLast Emperor's Capacitor Runecarving Power\nChi spenders increase the damage of your next Crackling Jade Lightning by 100% and reduce its cost by 5%, stacking up to 20 times.\nRunecarve on: Waist, Legs\nSource: Raid Drop: Artificer Xy'mox\nRequires: Monk (Windwalker)" }
entries[183297] = { ["name"] = "Memory of Xuen", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nXuen's Battlegear Runecarving Power\nRising Sun Kick critical strikes reduce the cooldown of Fists of Fury by 5.0 sec.\n\nWhen Fists of Fury ends, the critical strike chance of Rising Sun Kick is increased by 40% for 5 sec.\nRunecarve on: Chest, Back\nSource: Dungeon Drop: Kryxis the Voracious\nRequires: Monk (Windwalker)" }
entries[183298] = { ["name"] = "Memory of the Mad Paragon", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThe Mad Paragon Runecarving Power\nHammer of Wrath deals 30% additional damage and extends the duration of [ Crusade ] [ Avenging Crusader / Avenging Wrath ] by 1 sec.\nRunecarve on: Waist, Feet\nSource: Quest: The Great Vault\nRequires: Paladin" }
entries[183299] = { ["name"] = "Memory of the Sun's Cycles", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nOf Dusk and Dawn Runecarving Power\nWhen you reach 5 Holy Power, you gain Blessing of Dawn. When you reach 0 Holy Power, you gain Blessing of Dusk.\n\nBlessing of Dawn\nDamage and healing increased by 6% for 12 sec.\n\nBlessing of Dusk\nDamage taken reduced by 4% for 12 sec.\nRunecarve on: Head, Neck, Shoulder\nSource: Raid Drop: Stone Legion Generals\nRequires: Paladin" }
entries[183300] = { ["name"] = "Memory of the Magistrate's Judgment", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThe Magistrate's Judgment Runecarving Power\nJudgment has a [ Holy : 60% / Protection : 45% /\n\nRetribution\n75% ] chance to reduce the cost of your next Holy Power spender by 1. (700ms cooldown)\nRunecarve on: Wrist, Finger\nSource: Dungeon Drop: Xav the Unfallen\nRequires: Paladin" }
entries[183301] = { ["name"] = "Memory of Uther", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nUther's Devotion Runecarving Power\nYour Blessing of Freedom [ Blessing of Sacrifice : Blessing of Sacrifice ] and [ Blessing of Spellwarding / Blessing of Protection] cooldowns are reduced by 1 sec per Holy Power spent.\nRunecarve on: Neck, Chest\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Paladin" }
entries[183302] = { ["name"] = "Memory of the Sunwell's Bloom", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nInflorescence of the Sunwell Runecarving Power\nInfusion of Light has 1 additional charge and its effects are increased by 30%.\nRunecarve on: Feet, Back\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Paladin (Holy)" }
entries[183303] = { ["name"] = "Memory of Maraad's Dying Breath", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMaraad's Dying Breath Runecarving Power\nLight of Dawn increases your next Light of the Martyr by 10% for each ally healed, and allows that Light of the Martyr to heal through Beacon of Light.\n\nLight of the Martyr damages you over 5 sec instead of instantly.\nRunecarve on: Chest, Finger\nSource: Dungeon Drop: Grand Proctor Beryllia\nRequires: Paladin (Holy)" }
entries[183304] = { ["name"] = "Memory of the Shadowbreaker", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nShadowbreaker, Dawn of the Sun Runecarving Power\nLight of Dawn's range is increased to 40 yards. All allies within your Light of Dawn benefit from Mastery: Lightbringer as though they were within 10 yards for 8 sec.\n\nWord of Glory receives 50% increased benefit from your Mastery.\nRunecarve on: Shoulder, Waist, Hands\nSource: Raid Drop: Sun King's Salvation\nRequires: Paladin (Holy)" }
entries[183305] = { ["name"] = "Memory of the Shock Barrier", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nShock Barrier Runecarving Power\nHoly Shock protects the target with a shield of Holy Light for 18 sec, absorbing damage equal to 20% of the Holy Shock every 6 sec. Can protect up to 5 targets.\nRunecarve on: Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Paladin (Holy)" }
entries[183306] = { ["name"] = "Memory of the Righteous Bulwark", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBulwark of Righteous Fury Runecarving Power\nAvenger's Shield increases the damage of your next Shield of the Righteous by 30% for each target hit by Avenger's Shield, stacking up to 5 times, and increases its radius by 6 yds.\nRunecarve on: Shoulder, Finger\nSource: Dungeon Drop: High Adjudicator Aleez\nRequires: Paladin (Protection)" }
entries[183307] = { ["name"] = "Memory of a Holy Sigil", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nHoly Avenger's Engraved Sigil Runecarving Power\nYour Avenger's Shield has a 35% chance to have its cooldown instantly reset when used. (Proc chance: 35%)\nRunecarve on: Head, Waist\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Paladin (Protection)" }
entries[183308] = { ["name"] = "Memory of the Endless Kings", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nReign of Endless Kings Runecarving Power\nWhen you drop below 20% health, you become infused with Guardian of the Ancient Kings for 4 sec. This cannot occur again for 45 sec.\nRunecarve on: Neck, Chest, Wrist\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Paladin (Protection)" }
entries[183309] = { ["name"] = "Memory of the Ardent Protector", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThe Ardent Protector's Sanctum Runecarving Power\nWhen Ardent Defender saves you from death, it restores 40% additional health.\n\nWhen Ardent Defender expires without saving you from death, reduce its remaining cooldown by 40%.\nRunecarve on: Neck, Wrist\nSource: Raid Drop: Sludgefist\nRequires: Paladin (Protection)" }
entries[183310] = { ["name"] = "Memory of the Vanguard's Momentum", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nVanguard's Momentum Runecarving Power\nHammer of Wrath has 1 extra charge and increases Holy damage done by 4% for 10 sec, stacking 3 times.\nRunecarve on: Head, Feet, Hands\nSource: Raid Drop: Sire Denathrius\nRequires: Paladin (Retribution)" }
entries[183311] = { ["name"] = "Memory of the Final Verdict", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFinal Verdict Runecarving Power 10 yd range\nRequires level 1\nReplaces Templar's Verdict with Final Verdict, a devastating strike that deals (144.95% of Attack Power) Holy damage. Has a 15% chance to activate Hammer of Wrath and reset its cooldown.\nRunecarve on: Chest, Back\nSource: World Boss Drop: Valinor, the Light of Eons\nRequires: Paladin (Retribution)" }
entries[183312] = { ["name"] = "Memory of a Relentless Inquisitor", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRelentless Inquisitor Runecarving Power\nSpending Holy Power grants you 1% haste per finisher for 12 sec, stacking up to 5 times. (500ms cooldown)\nRunecarve on: Legs, Back\nSource: Drop: Torghast, Tower of the Damned. The Upper Reaches, Layer 3+\nRequires: Paladin" }
entries[183313] = { ["name"] = "Memory of the Lightbringer's Tempest", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nTempest of the Lightbringer Runecarving Power\nDivine Storm projects an additional wave of light, striking all enemies up to 20 yards in front of you for 20% of Divine Storm's damage.\nRunecarve on: Waist, Legs\nSource: Dungeon Drop: Oryphrion\nRequires: Paladin (Retribution)" }
entries[183314] = { ["name"] = "Memory of Cauterizing Shadows", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCauterizing Shadows Runecarving Power\nWhen [ Purge the Wicked / Shadow Word: Pain] expires on a target, 3 allies within 30 yds of the target are healed for (75% of Spell Power).\nRunecarve on: Waist, Feet\nSource: Dungeon Drop: Mordretha, the Endless Empress\nRequires: Priest" }
entries[183315] = { ["name"] = "Memory of Measured Contemplation", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMeasured Contemplation Runecarving Power\nFor every 15 seconds that you do not cast Flash Heal, the healing of your next Flash Heal is increased by 50%. This effect can stack up to 4 times.\nRunecarve on: Neck, Chest\nSource: Quest: The Great Vault\nRequires: Priest" }
entries[183316] = { ["name"] = "Memory of the Twins of the Sun Priestess", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nTwins of the Sun Priestess Runecarving Power\nPower Infusion also grants you 100% of its effects when used on an ally.\nRunecarve on: Head, Neck, Shoulder\nSource: Raid Drop: Stone Legion Generals\nRequires: Priest" }
entries[183317] = { ["name"] = "Memory of a Heavenly Vault", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nVault of Heavens Runecarving Power\nLeap of Faith instead causes you to leap to your target, and has 2 charges.\nRunecarve on: Wrist, Finger\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Priest" }
entries[183318] = { ["name"] = "Memory of a Clear Mind", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nClarity of Mind Runecarving Power\n[ Spirit Shell : Spirit Shell increases the duration of active Atonements by 3 sec, and reduces the mana cost of damage dealing spells by 30% / During Rapture, Power Word: Shield costs 20% less mana and applies 6 second longer Atonements.] (Proc chance: 50%)\nRunecarve on: Chest, Finger\nSource: Raid Drop: Sludgefist\nRequires: Priest (Discipline)" }
entries[183319] = { ["name"] = "Memory of my Crystalline Reflection", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCrystalline Reflection Runecarving Power\nPower Word: Shield instantly heals the target for (42% of Spell Power) and reflects 20% of damage absorbed.\nRunecarve on: Shoulder, Hands\nSource: Dungeon Drop: Margrave Stradama\nRequires: Priest (Discipline)" }
entries[183320] = { ["name"] = "Memory of the Kiss of Death", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nKiss of Death Runecarving Power\nReduces Shadow Word: Death's cooldown by 12 sec and causes its damage to trigger Atonement when used on targets below (85% of Spell Power)% health.\nRunecarve on: Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Priest (Discipline)" }
entries[183321] = { ["name"] = "Memory of the Penitent One", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThe Penitent One Runecarving Power\nPower Word: Radiance has a 60% chance to cause your next Penance to be free and fire 3 extra bolts.\nRunecarve on: Feet, Back\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Priest (Discipline)" }
entries[183322] = { ["name"] = "Memory of a Divine Image", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDivine Image Runecarving Power\nWhen you use a Holy Word spell, you have a chance to summon an image of a Naaru at your side. For 15 sec, whenever you cast a spell, the Naaru will cast a similar spell. (Proc chance: 25%)\nRunecarve on: Head, Waist, Back\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Priest (Holy)" }
entries[183323] = { ["name"] = "Memory of Flash Concentration", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFlash Concentration Runecarving Power\nEach time you cast Flash Heal, Heal has its casting time reduced by 0.2 sec and healing increased by 3% for 20 sec, stacking up to 5 times.\nRunecarve on: Neck, Wrist\nSource: Dungeon Drop: Grand Proctor Beryllia\nRequires: Priest (Holy)" }
entries[183324] = { ["name"] = "Memory of a Harmonious Apparatus", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nHarmonious Apparatus Runecarving Power\nCircle of Healing reduces the cooldown of Holy Word: Sanctify, Prayer of Mending reduces the cooldown of Holy Word: Serenity, and Holy Fire reduces the cooldown of Holy Word: Chastise by 4 sec.\nRunecarve on: Shoulder, Finger\nSource: Raid Drop: Sire Denathrius\nRequires: Priest (Holy)" }
entries[183325] = { ["name"] = "Memory of Archbishop Benedictus", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nX'anshi, Return of Archbishop Benedictus Runecarving Power\nAfter Spirit of Redemption expires, you will revive at up to 100% health, based on your effectiveness during Spirit of Redemption. After reviving, you cannot benefit from Spirit of Redemption for 10 min.\nRunecarve on: Legs, Back\nSource: World Boss Drop: Valinor, the Light of Eons\nRequires: Priest (Holy)" }
entries[183326] = { ["name"] = "Memory of the Void's Eternal Call", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEternal Call to the Void Runecarving Power Approximately 1.3 procs per minute\nMind Flay and Mind Sear have a chance to spawn a Void Tendril or Void Lasher that channels at your target for 15 sec, generating 3 insanity every 1 sec.\nRunecarve on: Wrist, Hands\nSource: Raid Drop: The Council of Blood\nRequires: Priest (Shadow)" }
entries[183327] = { ["name"] = "Memory of the Painbreaker Psalm", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nPainbreaker Psalm Runecarving Power\nShadow Word: Death consumes 8 sec of Shadow Word: Pain and Vampiric Touch, instantly dealing that damage to the target and generating up to 30 Insanity.\nRunecarve on: Chest, Back\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Priest (Shadow)" }
entries[183328] = { ["name"] = "Memory of Talbadar", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nTalbadar's Stratagem Runecarving Power\nWhile you have Shadow Word: Pain, Devouring Plague, and Vampiric Touch active on the same target, your Mind Blast deals 55% more damage.\nRunecarve on: Waist, Legs\nSource: Drop: Torghast, Tower of the Damned. The Upper Reaches, Layer 3+\nRequires: Priest (Shadow)" }
entries[183329] = { ["name"] = "Memory of a Prism of Shadow and Fire", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nShadowflame Prism Runecarving Power\nMind Blast and Shadow Word: Death cause your Shadowfiend to teleport behind your target, slashing up to 5 nearby enemies for [ Mindbender : [.442 * (190% of Spell Power)] / [.408 * (190% of Spell Power)]] Shadowflame damage. Each time a rift is triggered, the duration of Shadowfiend is increased by 1.0 sec.\nRunecarve on: Head, Hands\nSource: Dungeon Drop: Mueh'zala\nRequires: Priest (Shadow)" }
entries[183330] = { ["name"] = "Memory of Bloodfang's Essence", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEssence of Bloodfang Runecarving Power\nYour combo point generating abilities have a chance to infect the target with Bloodfang, causing 0 Bleed damage over 6 sec, and healing you for 50% of the damage dealt. (Proc chance: 30%, 200ms cooldown)\nRunecarve on: Head, Shoulder, Finger\nSource: Raid Drop: Stone Legion Generals\nRequires: Rogue" }
entries[183331] = { ["name"] = "Memory of Invigorating Shadowdust", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nInvigorating Shadowdust Runecarving Power\nVanish reduces the remaining cooldown of your other abilities by 20 sec.\nRunecarve on: Neck, Chest\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Rogue" }
entries[183332] = { ["name"] = "Memory of the Master Assassin's Mark", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMark of the Master Assassin Runecarving Power\nWhile Stealth is active and for 4 sec after breaking Stealth, your Critical Strike chance is increased by 100%.\nRunecarve on: Wrist, Finger\nSource: Dungeon Drop: An Affront of Challengers\nRequires: Rogue" }
entries[183333] = { ["name"] = "Memory of Tiny Toxic Blade", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nTiny Toxic Blade Runecarving Power\nShiv deals 500% increased damage and no longer costs Energy.\nRunecarve on: Waist, Feet\nSource: Quest: The Great Vault\nRequires: Rogue" }
entries[183334] = { ["name"] = "Memory of the Dashing Scoundrel", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDashing Scoundrel Runecarving Power\nEnvenom also increases the critical strike chance of your poisons by 15%, and their critical strikes generate 1 Energy.\nRunecarve on: Feet, Back\nSource: Raid Drop: The Council of Blood\nRequires: Rogue (Assassination)" }
entries[183335] = { ["name"] = "Memory of the Doomblade", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDoomblade Runecarving Power\nMutilate deals an additional 45% Bleed damage over 8 sec.\n\nEnvenom damage increased by 5% for each Bleed you have on the target.\nRunecarve on: Shoulder, Hands, Back\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Rogue (Assassination)" }
entries[183336] = { ["name"] = "Memory of the Duskwalker's Patch", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDuskwalker's Patch Runecarving Power\nThe remaining cooldown on Deathmark is reduced by 1 sec for every 30 Energy you expend.\nRunecarve on: Chest, Finger\nSource: Dungeon Drop: Mistcaller\nRequires: Rogue (Assassination)" }
entries[183337] = { ["name"] = "Memory of the Zoldyck Insignia", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nZoldyck Insignia Runecarving Power\nYour Poisons and Bleeds deal 30% increased damage to targets below 30% health.\nRunecarve on: Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Rogue (Assassination)" }
entries[183338] = { ["name"] = "Memory of Celerity", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCelerity Runecarving Power\nAdrenaline Rush increases your damage by 8%, and you have a chance while Slice and Dice is active to gain the Adrenaline Rush effect for 3 sec.\nRunecarve on: Shoulder, Finger\nSource: Dungeon Drop: Ventunax\nRequires: Rogue (Outlaw)" }
entries[183339] = { ["name"] = "Memory of a Concealed Blunderbuss", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nConcealed Blunderbuss Runecarving Power\nWhen Sinister Strike hits an additional time, there is a 40% chance that your next Pistol Shot will fire 3 additional times.\nRunecarve on: Wrist, Hands\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Rogue (Outlaw)" }
entries[183340] = { ["name"] = "Memory of Greenskin", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nGreenskin's Wickers Runecarving Power\nBetween the Eyes has a 20% chance per Combo Point to increase the damage of your next Pistol Shot by 300%.\nRunecarve on: Head, Waist\nSource: Raid Drop: Sludgefist\nRequires: Rogue (Outlaw)" }
entries[183341] = { ["name"] = "Memory of a Guile Charm", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nGuile Charm Runecarving Power\nTake advantage of the natural ebb and flow of combat, causing your Sinister Strike to gradually increase your damage dealt by up to 15%. This maximum effect will last for 12 sec before fading and beginning the cycle anew.\nRunecarve on: Neck, Wrist\nSource: World Boss Drop: Mortanis\nRequires: Rogue (Outlaw)" }
entries[183342] = { ["name"] = "Memory of Akaari's Soul Fragment", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nAkaari's Soul Fragment Runecarving Power\nAfter using Shadowstrike or Cheap Shot, your target suffers a Shadowstrike from the shadows 2 sec later, at 25% effectiveness.\nRunecarve on: Head, Neck, Hands\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Rogue (Subtlety)" }
entries[183343] = { ["name"] = "Memory of the Deathly Shadows", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeathly Shadows Runecarving Power\nVanish grants 5 combo points and increases all damage dealt by [ Subtlety : 20% for 15 sec /\n\nAssassination, Outlaw\n15% for 12 sec ] (500ms cooldown)\nRunecarve on: Waist, Legs\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Rogue" }
entries[183344] = { ["name"] = "Memory of Finality", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFinality Runecarving Power\nEviscerate, Rupture, and Black Powder increase the damage of your next use of the finishing move by 25%.\nRunecarve on: Chest, Back\nSource: Raid Drop: Sire Denathrius\nRequires: Rogue (Subtlety)" }
entries[183345] = { ["name"] = "Memory of the Rotten", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThe Rotten Runecarving Power\nAfter activating Symbols of Death, your next Shadowstrike or [ Gloomblade / Backstab] deals 50% increased damage and generates 4 additional combo points.\nRunecarve on: Legs, Back\nSource: Dungeon Drop: Domina Venomblade\nRequires: Rogue (Subtlety)" }
entries[183346] = { ["name"] = "Memory of an Ancestral Reminder", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nAncestral Reminder Runecarving Power\n[ Heroism / Bloodlust] or any similar effects last an additional 20.0 sec on you, and you gain an extra 10% Haste from any [ Heroism / Bloodlust] type effect.\nRunecarve on: Wrist, Finger\nSource: Raid Drop: Stone Legion Generals\nRequires: Shaman" }
entries[183347] = { ["name"] = "Memory of Devastating Chains", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nChains of Devastation Runecarving Power Instant\nElemental\nCasting Chain Heal makes your next Chain Lightning instant cast and deal 50% increased damage. Casting Chain Lightning makes your next Chain Heal instant cast and consume no mana.\n\nEnhancement, Restoration\nCasting Chain Heal makes your next Chain Lightning instant cast. Casting Chain Lightning makes your next Chain Heal instant cast.\nRunecarve on: Neck, Chest\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Shaman" }
entries[183348] = { ["name"] = "Memory of Deeply Rooted Elements", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeeply Rooted Elements Runecarving Power\nElemental\nCasting Lava Burst has a 7% chance to activate Ascendance for 6.0 sec.\n\nRestoration\nCasting Riptide has a 7% chance to activate Ascendance for 6.0 sec.\n\nEnhancement\nUsing Stormstrike has a 8% chance to activate Ascendance for 6.0 sec.\nRunecarve on: Head, Shoulder, Wrist\nSource: Quest: The Great Vault\nRequires: Shaman" }
entries[183349] = { ["name"] = "Memory of the Deeptremor Stone", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeeptremor Stone Runecarving Power\nEarth Elemental has a permanent Earthquake attached to it.\nRunecarve on: Waist, Feet, Finger\nSource: Dungeon Drop: Echelon\nRequires: Shaman" }
entries[183350] = { ["name"] = "Memory of the Great Sundering", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEchoes of Great Sundering Runecarving Power\nWhen you cast Earth Shock, your next Earthquake will deal 120% additional damage.\nRunecarve on: Shoulder, Hands\nSource: Dungeon Drop: Mueh'zala\nRequires: Shaman (Elemental)" }
entries[183351] = { ["name"] = "Memory of an Elemental Equilibrium", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nElemental Equilibrium Runecarving Power\nDealing direct Fire, Frost, and Nature damage within 10 sec will increase all damage dealt by 15% for 10 sec. This can only occur once every 30 sec.\nRunecarve on: Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Shaman (Elemental)" }
entries[183352] = { ["name"] = "Memory of the Demise of Skybreaker", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSkybreaker's Fiery Demise Runecarving Power\nFlame Shock damage over time critical strikes reduce the cooldown of [ Storm Elemental / Fire Elemental] by [ Storm Elemental : 1.0 / 1.0] sec, and Flame Shock has a 50% increased critical strike chance.\nRunecarve on: Chest, Finger\nSource: Raid Drop: Sire Denathrius\nRequires: Shaman (Elemental)" }
entries[183353] = { ["name"] = "Memory of the Windspeaker's Lava Resurgence", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nWindspeaker's Lava Resurgence Runecarving Power\nWhen you cast Earth Shock, gain Lava Surge and increase the damage of your next Lava Burst by 20%.\nRunecarve on: Feet, Back\nSource: World Boss Drop: Valinor, the Light of Eons\nRequires: Shaman (Elemental)" }
entries[183354] = { ["name"] = "Memory of the Doom Winds", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDoom Winds Runecarving Power\nDropping Windfury Totem grants you 100% chance to gain Windfury Weapon and increases Windfury Weapon damage by 25% for 12 sec.\n\nThis can only occur once every 1 min.\nRunecarve on: Head, Waist, Back\nSource: Dungeon Drop: Devos, Paragon of Doubt\nRequires: Shaman (Enhancement)" }
entries[183355] = { ["name"] = "Memory of the Frost Witch", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nLegacy of the Frost Witch Runecarving Power\nConsuming 5 stacks of Maelstrom Weapon will reset the cooldown of Stormstrike and cause your next Stormstrike to deal 30% increased damage.\nRunecarve on: Neck, Wrist\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Shaman (Enhancement)" }
entries[183356] = { ["name"] = "Memory of the Primal Lava Actuators", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nPrimal Lava Actuators Runecarving Power\nEach time Flame Shock deals Periodic damage, increase the damage of your next Lava Lash by 12% and reduce the cooldown of Lava Lash by 0.5 sec.\nRunecarve on: Wrist, Hands\nSource: Raid Drop: Sludgefist\nRequires: Shaman (Enhancement)" }
entries[183357] = { ["name"] = "Memory of the Witch Doctor", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nWitch Doctor's Wolf Bones Runecarving Power\nIncreases the chance to gain a stack of Maelstrom Weapon by 3%, and whenever you gain a stack of Maelstrom Weapon, the cooldown of Feral Spirits is reduced by 2.0 sec.\nRunecarve on: Shoulder, Finger\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Shaman (Enhancement)" }
entries[183358] = { ["name"] = "Memory of an Earthen Harmony", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEarthen Harmony Runecarving Power\nEarth Shield healing is increased by 150% if your Earth Shield target is below 75% health, and Healing Wave adds a stack of Earth Shield to your target, up to 9 maximum stacks.\nRunecarve on: Chest, Back\nSource: Dungeon Drop: General Kaal\nRequires: Shaman (Restoration)" }
entries[183359] = { ["name"] = "Memory of Jonat", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nJonat's Natural Focus Runecarving Power\nHealing Wave and Healing Surge increase the healing done by your next Chain Heal by 20%, stacking up to 5 times.\nRunecarve on: Waist, Legs\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Shaman (Restoration)" }
entries[183360] = { ["name"] = "Memory of the Primal Tide Core", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nPrimal Tide Core Runecarving Power\nEvery 4 casts of Riptide also applies Riptide to another friendly target near your Riptide target.\nRunecarve on: Head, Hands\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Shaman (Restoration)" }
entries[183361] = { ["name"] = "Memory of the Spiritwalker's Tidal Totem", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSpiritwalker's Tidal Totem Runecarving Power\nAfter using Mana Tide Totem, the cast time of Healing Wave and Chain Heal is reduced by 50%, and the mana cost of Chain Heal and Healing Wave is reduced by 40% for 10 sec.\nRunecarve on: Legs, Back\nSource: Raid Drop: Huntsman Altimor\nRequires: Shaman (Restoration)" }
entries[183362] = { ["name"] = "Memory of a Malefic Wrath", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMalefic Wrath Runecarving Power\nMalefic Rapture increases the damage of your [ Drain Soul / Shadow Bolt] by 35% for 10 sec, stacking up to 3 times. (100ms cooldown)\nRunecarve on: Shoulder, Hands\nSource: Raid Drop: Sire Denathrius\nRequires: Warlock (Affliction)" }
entries[183363] = { ["name"] = "Memory of Azj'Aqir's Agony", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nPerpetual Agony of Azj'Aqir Runecarving Power\nAgony has a 20% increased chance to generate a Soul Shard.\nRunecarve on: Chest, Finger\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Warlock (Affliction)" }
entries[183364] = { ["name"] = "Memory of Sacrolash's Dark Strike", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSacrolash's Dark Strike Runecarving Power\nCorruption damage is increased by 25%, and each time it deals damage any of your Curses active on the target are extended by 2 sec.\nRunecarve on: Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Warlock (Affliction)" }
entries[183365] = { ["name"] = "Memory of the Consuming Wrath", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nWrath of Consumption Runecarving Power\nCorruption and Agony each grant an application of Wrath of Consumption when a target dies, increasing all periodic damage dealt by 6% for 30 sec, stacking up to 5 times.\nRunecarve on: Feet, Back\nSource: Dungeon Drop: Ventunax\nRequires: Warlock (Affliction)" }
entries[183366] = { ["name"] = "Memory of the Claw of Endereth", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nClaw of Endereth Runecarving Power\nDrain Life now channels 100% faster and restores health 100% faster.\nRunecarve on: Waist, Feet\nSource: Quest: The Great Vault\nRequires: Warlock" }
entries[183367] = { ["name"] = "Memory of Demonic Synergy", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRelic of Demonic Synergy Runecarving Power Approximately 3 procs per minute\nDamage done by you or your primary demon has a chance to grant the other one [ Demonology : 15% /\n\nAffliction, Destruction\n10% ] increased damage for 15 sec.\nRunecarve on: Head, Shoulder, Back\nSource: Raid Drop: Stone Legion Generals\nRequires: Warlock" }
entries[183368] = { ["name"] = "Memory of the Dark Portal", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nPillars of the Dark Portal Runecarving Power\nDemonic Gateway is now instant cast, and your first use of your gateway does not trigger its cooldown.\n\nIn addition, nether energy lashes enemies you pass through, knocking them away.\nRunecarve on: Neck, Chest\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Warlock\nModifies Cast Time -100%:\nDemonic Gateway" }
entries[183369] = { ["name"] = "Memory of Wilfred's Sigil of Superior Summoning", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nWilfred's Sigil of Superior Summoning Runecarving Power\nAffliction\nEvery Soul Shard you spend reduces the cooldown of Summon Darkglare by 2.0 sec.\n\nDemonology\nEvery Soul Shard you spend reduces the cooldown of Summon Demonic Tyrant by 0.6 sec.\n\nDestruction\nEvery Soul Shard you spend reduces the cooldown of Summon Infernal by 1.5 sec.\nRunecarve on: Wrist, Finger\nSource: Dungeon Drop: The Manastorms\nRequires: Warlock" }
entries[183370] = { ["name"] = "Memory of the Core of the Balespider", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBalespider's Burning Core Runecarving Power\nShadow Bolt increases the damage of your Demonbolt by 15%, stacking up to 4 times. Lasts 20 sec.\nRunecarve on: Wrist, Hands\nSource: Raid Drop: Artificer Xy'mox\nRequires: Warlock (Demonology)" }
entries[183371] = { ["name"] = "Memory of the Horned Nightmare", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nForces of the Horned Nightmare Runecarving Power\nHand of Gul'dan has a 15% chance to cast a second time on your target for free.\nRunecarve on: Shoulder, Finger\nSource: Drop: Torghast, Tower of the Damned. Fracture Chambers, Layer 3+\nRequires: Warlock (Demonology)" }
entries[183372] = { ["name"] = "Memory of the Grim Inquisitor", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nGrim Inquisitor's Dread Calling Runecarving Power\nEach Soul Shard spent on Hand of Gul'dan increases the damage of your next Call Dreadstalkers by 4%.\nRunecarve on: Neck, Wrist\nSource: Drop: Torghast, Tower of the Damned. The Upper Reaches, Layer 3+\nRequires: Warlock (Demonology)" }
entries[183373] = { ["name"] = "Memory of an Implosive Potential", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nImplosive Potential Runecarving Power\nImplosion grants 1% haste for 12 sec for each Imp exploded. When this damages at least 3 targets, instead gain 5% haste per Imp. A maximum of 15 exploded Imps can grant this benefit.\nRunecarve on: Head, Waist, Hands\nSource: Dungeon Drop: Surgeon Stitchflesh\nRequires: Warlock (Demonology)" }
entries[183374] = { ["name"] = "Memory of Azj'Aqir's Cinders", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCinders of the Azj'Aqir Runecarving Power\nConflagrate has 1 additional charge and has its recharge time reduced by 3.0 sec.\nRunecarve on: Legs, Back\nSource: Raid Drop: Sludgefist\nRequires: Warlock (Destruction)" }
entries[183375] = { ["name"] = "Memory of the Diabolic Raiment", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEmbers of the Diabolic Raiment Runecarving Power\nIncinerate now generates 100% additional Soul Shard Fragments.\nRunecarve on: Chest, Back\nSource: Dungeon Drop: Kul'tharok\nRequires: Warlock (Destruction)" }
entries[183376] = { ["name"] = "Memory of Azj'Aqir's Madness", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMadness of the Azj'Aqir Runecarving Power\nChaos Bolt increases the damage of Chaos Bolt by 25% and reduces the cast time of Chaos Bolt by 20% for 4 sec.\nRunecarve on: Head, Hands\nSource: World Boss Drop: Nurgash Muckformed\nRequires: Warlock (Destruction)" }
entries[183377] = { ["name"] = "Memory of the Ymirjar", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nOdr, Shawl of the Ymirjar Runecarving Power\nEnemies marked by your Havoc take 25% increased damage from your single target spells.\nRunecarve on: Waist, Legs\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Warlock (Destruction)" }
entries[183378] = { ["name"] = "Memory of the Leaper", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\nPurchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\n\nLeaper Runecarving Power\nHeroic Leap gains 2 additional charges.\nRunecarve on: Waist, Feet\nSource: Purchased for Honor from Purveyor Zo'kuul. Must have Runecarving unlocked to purchase this memory.\nRequires: Warrior" }
entries[183379] = { ["name"] = "Memory of the Misshapen Mirror", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nMisshapen Mirror Runecarving Power\nSpell Reflection lasts 60% longer and applies to your nearest ally. (1s cooldown)\nRunecarve on: Neck, Chest\nSource: Quest: The Great Vault\nRequires: Warrior" }
entries[183380] = { ["name"] = "Memory of a Seismic Reverberation", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSeismic Reverberation Runecarving Power\nProtection ( Protection Warrior )\nIf Whirlwind or Revenge hits 3 or more enemies, it hits them 1 additional time for 75% damage.\n\nArms, Fury\nIf Whirlwind [ Protection : or Revenge ]hits 3 or more enemies, it hits them 1 additional time for [ Arms : 80 ] [ Fury : 100 ] [ Protection : 75 / 100 ]% damage.\nRunecarve on: Head, Shoulder, Feet\nSource: Dungeon Drop: Halkias, the Sin-Stained Goliath\nRequires: Warrior" }
entries[183381] = { ["name"] = "Memory of the Tormented Kings", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSignet of Tormented Kings Runecarving Power\nActivating Bladestorm, Recklessness, or Avatar randomly casts one of the other two abilities at reduced effectiveness.\nRunecarve on: Wrist, Finger\nSource: Raid Drop: Stone Legion Generals\nRequires: Warrior" }
entries[183382] = { ["name"] = "Memory of a Battlelord", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBattlelord Runecarving Power\nYour Overpower has a 40% chance to reset the cooldown of Mortal Strike and reduce the Rage cost of your next Mortal Strike by 15. (Proc chance: 40%, 100ms cooldown)\nRunecarve on: Neck, Wrist\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Warrior (Arms)" }
entries[183383] = { ["name"] = "Memory of an Enduring Blow", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nEnduring Blow Runecarving Power\nYour Mortal Strike has a 25% chance to apply the Colossus Smash effect to your target for 6 sec. (Proc chance: 25%)\nRunecarve on: Head, Waist\nSource: Drop: Torghast, Tower of the Damned. Skoldus Hall, Layer 3+\nRequires: Warrior (Arms)" }
entries[183384] = { ["name"] = "Memory of the Exploiter", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nExploiter Runecarving Power\nExecute causes the target to take 50% more damage from your next Mortal Strike, stacking up to 2 times.\nRunecarve on: Shoulder, Finger\nSource: Raid Drop: Sire Denathrius\nRequires: Warrior (Arms)" }
entries[183385] = { ["name"] = "Memory of the Unhinged", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nUnhinged Runecarving Power\nWhile Bladestorm is active, you automatically cast a total of 2 Mortal Strikes at random nearby enemies.\nRunecarve on: Wrist, Hands, Finger\nSource: Dungeon Drop: Xav the Unfallen\nRequires: Warrior (Arms)" }
entries[183386] = { ["name"] = "Memory of Fujieda", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCadence of Fujieda Runecarving Power\nBloodthirst increases your Haste by 1% for 12 sec, stacking up to 5 times. (500ms cooldown)\nRunecarve on: Waist, Legs\nSource: World Boss Drop: Mortanis\nRequires: Warrior (Fury)" }
entries[183387] = { ["name"] = "Memory of the Deathmaker", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeathmaker Runecarving Power\nRampage has a 30% chance to apply the Siegebreaker effect to your target for 6 sec. (Proc chance: 30%)\nRunecarve on: Legs, Back\nSource: Dungeon Drop: Amarth, The Harvester\nRequires: Warrior (Fury)" }
entries[183388] = { ["name"] = "Memory of a Reckless Defense", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nReckless Defense Runecarving Power\nRampage strikes have 20% chance to reduce the remaining cooldown of your Recklessness and Enraged Regeneration by 1 sec.\nRunecarve on: Head, Waist, Hands\nSource: Drop: Torghast, Tower of the Damned. Mort'regar, Layer 3+\nRequires: Warrior (Fury)" }
entries[183389] = { ["name"] = "Memory of the Berserker's Will", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nWill of the Berserker Runecarving Power\nWhen Recklessness expires, your Critical Strike is increased by 7% for 12 sec. Your Raging Blow will refresh the duration of this effect.\nRunecarve on: Chest, Back\nSource: Raid Drop: Sludgefist\nRequires: Warrior (Fury)" }
entries[183390] = { ["name"] = "Memory of a Reprisal", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nReprisal Runecarving Power\nCharge and Intervene grant you Shield Block for 4 sec, Revenge!, and generate 20 Rage. (100ms cooldown)\nRunecarve on: Legs, Feet\nSource: Drop: Torghast, Tower of the Damned. The Upper Reaches, Layer 3+\nRequires: Warrior (Protection)" }
entries[183391] = { ["name"] = "Memory of the Wall", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThe Wall Runecarving Power\nShield Slam generates an additional 5 Rage and reduces the remaining cooldown of Shield Wall by 5 sec.\nRunecarve on: Shoulder, Back\nSource: Raid Drop: Hungering Destroyer\nRequires: Warrior (Protection)" }
entries[183392] = { ["name"] = "Memory of the Thunderlord", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nThunderlord Runecarving Power\nEach enemy hit by Thunder Clap reduces the remaining cooldown on Demoralizing Shout by 1.5 sec, up to 4.5 sec.\nRunecarve on: Feet, Hands\nSource: Dungeon Drop: Oryphrion\nRequires: Warrior (Protection)" }
entries[183393] = { ["name"] = "Memory of an Unbreakable Will", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nUnbreakable Will Runecarving Power\nShield Wall gains 1 additional charge, and grants 50% of its effect to all party members.\nRunecarve on: Chest, Finger\nSource: Drop: Torghast, Tower of the Damned. Coldheart Interstitia, Layer 3+\nRequires: Warrior (Protection)" }
