entries[183787] = { ["name"] = "Stygic Dampener", ["text"] = "Ethereal\nThe Maw\nBinds when picked up\nUnique\nDuration: 10 min (real time)\nUse: Summons a Stygic Dampener that increases the damage taken by the Gorged Shadehound by 20% and reduces damage taken by anyone near it by 20%.\n\nUsable in the Prodigum and Pit of Anguish.\nSell Price:" }
