entries[183793] = { ["name"] = "Empyrean Refreshment", ["text"] = "Use: Set out an Empyrean Refreshment to feed up to 35 people in your raid or party!\n\nRestores 86538 health and 115385 mana over 20 sec. Must remain seated while eating. (5 Min Cooldown)" }
