entries[183797] = { ["name"] = "Crusader's Dressing", ["text"] = "Quest Item\nUse: Mends the wounds of an injured ally." }
entries[183798] = { ["name"] = "Silessa's Battle Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon Battle Gargon Silessa as a mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Silessa fought valiantly alongside her master in the great incursion by the Light, following the battle her master set her to guard over a vault room of great value.\"\nCovenant:\nVenthyr\nZone:\nRevendreth" }
entries[183799] = { ["name"] = "Shifting Catalyst", ["text"] = "Ethereal\nThe Maw\nBinds when picked up\nUnique\nDuration: 10 min (real time)\nUse: Places a Shifting Catalyst that when used grants the ability to Essence Shift around the battlefield.\n\nUsable in the Soulstained Fields or Torturer's Hovel of The Maw.\nRequires level 60 to 60 ( 60)\nSell Price:" }
entries[183800] = { ["name"] = "Amber Ardenmoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The brilliant orange hue of the amber ardenmoth signals to predators that it is dangerous to eat. Consuming one of these creatures will put a predator into a dreamless sleep for years.\"\nDrop:\nWild Hunt Supplies\nZone:\nArdenweald" }
entries[183801] = { ["name"] = "Vibrant Flutterwing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Marasmius\n- Revered\n\n\"These minty green moths are very friendly. They particularly enjoy having their head fuzz vigorously brushed. They also enjoy music and poetry.\"\nVendor:\nCortinarius\nZone:\nArdenweald" }
entries[183802] = { ["name"] = "Memory of the Forsworn", ["text"] = "Quest Item\n\"A tiny piece of Lysonia's memories of her time among the Forsworn.\"" }
