entries[183805] = { ["name"] = "Tranquil Spirit of the Cosmos", ["text"] = "Queen's Conservatory\nBinds when picked up\nUse: Infuse a Wildseed of Regrowth with this spirit.\n\"This spirit contains the essence of a very powerful, yet oddly calming, spirit.\"\nSell Price:" }
entries[183806] = { ["name"] = "Energetic Spirit of Curiosity", ["text"] = "Queen's Conservatory\nBinds when picked up\nUse: Infuse a Wildseed of Regrowth with this spirit.\n\"This spirit contains the essence of a very powerful and curious spirit.\"\nSell Price:" }
entries[183807] = { ["name"] = "Stygic Coercion", ["text"] = "Ethereal\nThe Maw\nBinds when picked up\nUnique\nDuration: 10 min (real time)\nUse: Coerces specific Death Elementals into providing transportation around the Beastwarrens.\n\nUsable in the Beastwarrens of The Maw.\nRequires level 60 to 60 ( 60)\nSell Price:" }
