entries[184016] = { ["name"] = "Skulker's Wing", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 [Agility or Strength]\nUse: Become the Skulking Predator for 10 sec, gaining 69 Speed and pouncing on the next enemy to come within 8 yds, dealing 3874 Physical damage. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[184017] = { ["name"] = "Bargast's Leash", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 [Agility or Strength]\nUse: Form a Huntsman's Bond with a target ally for 30 sec. 25% of damage you suffer will be redirected to your bonded ally, up to [ 11389 * (1 + Versatility)] total damage redirected. (2 Min Cooldown)\nSell Price:" }
entries[184018] = { ["name"] = "Splintered Heart of Al'ar", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 [Agility or Strength]\nEquip: Absorbs up to 10234 damage from a lethal attack. When this effect occurs, erupt in a burst of flames, inflicting [ 2433 * (1 + Versatility)] Fire damage to nearby allies and enemies, and recovering [ 7025 * (1 + Versatility)] health.\n\nThis effect can only occur once every 8 min.\nSell Price:" }
entries[184019] = { ["name"] = "Soul Igniter", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 Intellect\nUse: Activate Soul Igniter, sacrificing up to 2157 health over 15 sec to empower Blazing Surge.\n\nReactivate to cast Blazing Surge, dealing [ 1541 * (1 + Versatility)] Fire damage split between enemies in a 40 yd cone, plus up to 40% additional damage, based on how long Soul Igniter was active.\n\nDamage is increased per enemy struck, up to 5 enemies. (1 min Cooldown)\nSell Price:" }
entries[184020] = { ["name"] = "Tuft of Smoldering Plumage", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 Intellect\nUse: Infuse your ally with a tuft of phoenix plumes, healing them for [ 5199 * (1 + Versatility)] after 6 sec, increased by up to 25% based on your target's missing health. If your ally suffers lethal damage, this effect triggers instantly. (2 Min Cooldown)\nSell Price:" }
entries[184021] = { ["name"] = "Glyph of Assimilation", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 Intellect\nUse: Deal 1786 Arcane damage to an enemy over 10 sec.\n\nIf your target dies while afflicted with Glyph of Assimilation, your Mastery is increased by 160 for 2 times the duration remaining on the Glyph. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[184022] = { ["name"] = "Consumptive Infusion", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 Intellect\nEquip: Casting a damaging spell causes your next single target heal to grant 138 Leech for 10 sec. This effect may only occur once every 30 sec.\nSell Price:" }
entries[184023] = { ["name"] = "Gluttonous Spike", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 Strength\nEquip: Your damaging abilities have a high chance to deal 116 Physical damage, healing you for 300% of the damage dealt. If this effect overheals, deal [ 98 * 5 * (1 + Versatility)] Physical damage split between nearby enemies over 15 sec, but suppress the lifesteal effect.\n\nDamage increased per enemy struck, up to 5 enemies.\nSell Price:" }
entries[184024] = { ["name"] = "Macabre Sheet Music", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 [Agility or Strength or Intellect]\nUse: Four dance partners appear in a random pattern around you. Moving to each grants you 40 Haste and 23 Speed for 20 sec, stacking. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[184025] = { ["name"] = "Memory of Past Sins", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 [Agility or Strength]\nUse: Your next 5 damaging abilities inflict Shattered Psyche, dealing 651 Shadow damage and increasing the target's damage taken from Shattered Psyche by 1% for 5 sec, stacking up to 25 times. (1.5s cooldown) (2 Min Cooldown)\nSell Price:" }
entries[184026] = { ["name"] = "Hateful Chain", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+28 Agility\nEquip: While you have a greater health percentage than your target, your abilities have a very high chance to deal [ 181 * (1 + Versatility)] Physical damage.\n\nWhile you have a lower health percentage than your target, your abilities have a very high chance to heal you for [ 247 * (1 + Versatility)].\nSell Price:" }
entries[184027] = { ["name"] = "Stone Legion Heraldry", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+31 [Agility or Strength]\nEquip: Proclaim your allegiance to the Stone Legion, increasing your Versatility by 43 , increased by 5% for each Stone Legionnaire in your party.\nSell Price:" }
entries[184028] = { ["name"] = "Cabalist's Hymnal", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+31 Intellect\nEquip: Join the Crimson Chorus. Every minute, your Critical Strike swells by ( 43 * 3) over 30 sec. before returning to normal. This effect is increased by 5% for each member of the Crimson Chorus in your party.\nSell Price:" }
entries[184029] = { ["name"] = "Manabound Mirror", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+31 Intellect\nEquip: For every 3240 mana spent, store [ 277 * (1 + Versatility)] healing within the mirror, up to [ 2307 * (1 + Versatility)] for 30 sec.\nUse: Heal your target for [ 1586 * (1 + Versatility)] plus all healing stored within the mirror. (1 Min Cooldown)\nSell Price:" }
entries[184030] = { ["name"] = "Dreadfire Vessel", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+31 [Agility or Strength or Intellect]\nUse: Unleash incendiary flames at your target inflicting 2787 Fire damage. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[184031] = { ["name"] = "Sanguine Vintage", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+31 [Agility or Strength]\nUse: Absorb up to [ 4353 * (1 + Versatility)] damage for 6 sec, then heal for 200% of the shield's remaining amount. (1 Min Cooldown)\nSell Price:" }
